// Функция для склонения слова "шаблон"
function pluralizeTemplates(count) {
    const cases = [2, 0, 1, 1, 1, 2];
    const words = ['шаблон', 'шаблона', 'шаблонов'];
    
    const index = (count % 100 > 4 && count % 100 < 20) ? 
        2 : cases[Math.min(count % 10, 5)];
    
    return words[index];
}

// Функция инициализации данных приложения
function initAppData() {
    return { categories: defaultCategories, templates: defaultTemplates };
}

function initAppDataEditor() {
    // Загрузка данных из localStorage
    const savedCategories = localStorage.getItem('support-kb-categories');
    const savedTemplates = localStorage.getItem('support-kb-templates');

    let categories, templates;

    if (savedCategories) {
        categories = JSON.parse(savedCategories);
    } else {
        categories = defaultCategories;
    }

    if (savedTemplates) {
        templates = JSON.parse(savedTemplates);
    } else {
        templates = defaultTemplates;
    }

    return { categories, templates };
}
